export function ladderFor(id: PerimeterId): LadderRow[] {
  switch (id) {
    case "gerd":
      return GERD_LADDER;
    case "pubs":
      return PUB_LADDER;
    case "cet":
      return CET_LADDER;
    case "kti":
      return KTI_LADDER;
    case "uspto":
      return USPTO_LADDER;
    case "nonOecd":
      return NON_OECD_LADDER;
  }
}

export function curveFor(id: PerimeterId): CurvePoint[] {
  switch (id) {
    case "gerd":
      return GERD_CURVE;
    case "pubs":
      return PUB_CURVE;
    case "cet":
      return CET_CURVE;
    case "kti":
      return KTI_CURVE;
    case "uspto":
      return USPTO_CURVE;
    case "nonOecd":
      return NON_OECD_CURVE;
  }
}

export function fmtPct(n: number, digits = 1): string {
  return `${n.toFixed(digits)}%`;
}

export function fmtHhi(n: number): string {
  return n.toLocaleString("en-US");
}

export function fmtTn(n: number, digits = 2): string {
  return `??${n.toFixed(digits)}T`;
}

