    const rest = 100 - top.reduce((s, r) => s + r.sharePct, 0);
    return [
      ...top.map((r) => ({ name: r.short, value: r.sharePct, color: r.color })),
      {
        name: "RoW",
        value: Math.max(0, rest),
        color: SLATE,
      },
    ];
  }, [perimeter]);

